os.makedirs(out_dir, exist_ok=True)
path = os.path.join(out_dir, "sheets_10.jsonl")
with io.open(path, "w", encoding="utf-8") as f:
    for r in rows:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

n = len(rows)
avg = sum(r["оценка_1_5"] for r in rows) / n
stock = sum(1 for r in rows if r["набор_источник"] == "сток")
mix = sum(1 for r in rows if r["набор_источник"] == "смесь")
nn = sum(1 for r in rows if r["набор_источник"] == "нейросеть")
author = sum(1 for r in rows if r["набор_источник"] == "авторская съёмка")
val_cover = sum(1 for r in rows if r["обложка_люди"].startswith("Валентина"))
total_frames = sum(r["картинок"] for r in rows)
total_miss = sum(r["кадров_мимо"] for r in rows)
shares = [r["кадров_мимо"] / r["картинок"] for r in rows]
shares.sort()
med = shares[len(shares)//2]
stockish = sum(1 for r in rows if r["набор_источник"] in ("сток",) or any("сток" in p for p in r["проблемы"]))
print("n=%d avg=%.2f" % (n, avg))
print("source: author=%d stock=%d mix=%d nn=%d" % (author, stock, mix, nn))
print("stockish(by problems too)=%d" % stockish)
print("valentina_cover=%d" % val_cover)
print("frames=%d miss=%d share=%.3f median_share=%.3f" % (total_frames, total_miss, total_miss/total_frames, med))
print("ratings dist:", {k: sum(1 for r in rows if r["оценка_1_5"]==k) for k in range(1,6)})
print("repeat problem:", sum(1 for r in rows if any("овтор" in p for p in r["проблемы"])))
print("irrelevant problem:", sum(1 for r in rows if any("ерелевант" in p or "не по теме" in p for p in r["проблемы"])))
print("path", path)
